import { useEffect, useMemo, useState } from 'react';
import {
  Activity, Archive, ArrowRight, BarChart3, Bell, BookOpen, Check, CheckCircle2, ChevronRight,
  CirclePlus, ClipboardList, Clock3, Copy, Download, Edit3, FileText, Flag, Heart, History,
  BadgeCheck, LayoutDashboard, Menu, Pause, Pencil, PhoneCall, Play, Plus, RefreshCw, Search, Settings,
  ShoppingBag, Sparkles, Target, Trash2, TrendingDown, Trophy, UserRound, X
} from 'lucide-react';
import { supabase } from '@/lib/supabase';

type Product = { id: string; name: string; calls: number; consents: number; sales: number; crossSales: number; hours: number; consentTarget: number; ppsTarget: number; salesHourTarget: number; crossTarget: number };
type Task = { id: string; title: string; required: boolean; priority: 'Высокий' | 'Средний' | 'Низкий'; due: string; done: boolean };
type QualityMetric = { value: number; target: number; direction: 'min' | 'max'; snapshots: { value: number; at: string }[] };
type SaleLog = { id: string; type: 'sale' | 'cross'; product: string; at: string; comment: string };
type Diary = { id: string; date: string; worked: string; changed: string; result: string; next: string };
type Victory = { id: string; text: string; date: string };
type ShiftHistory = { id: string; date: string; tasksDone: number; tasksTotal: number; products: Product[]; quality: { csat: number; critical: number; green: number }; victories: Victory[]; diary?: Diary };
type AppState = { started: boolean; startedAt: string | null; products: Product[]; tasks: Task[]; quality: { csat: QualityMetric; critical: QualityMetric; green: QualityMetric }; logs: SaleLog[]; victories: Victory[]; diary: Diary[]; history: ShiftHistory[]; breaks: string[]; profile: { name: string; team: string }; lastSaved: string | null };

type Page = 'home' | 'tasks' | 'targets' | 'journal' | 'history' | 'library' | 'settings';

const productNames = ['Потребительский кредит', 'Накопительный счёт', 'Кредитная карта', 'СберПрайм', 'Другой продукт', 'Кросс-продажа'];
const tipItems = [
  ['CSAT', 'Как оставить клиенту ощущение заботы', 'Проверяй понимание и спокойно завершай разговор.'],
  ['ACSAT', 'Выше, чем просто продажи', 'Точность формулировок — тоже результат.'],
  ['Возражения', 'Спокойно. Уверенно. По делу.', 'Короткие ответы, которые возвращают диалог.'],
  ['Кросс-продажи', 'Больше возможностей для клиента', 'Сначала ценность основного предложения, затем кросс.'],
];
const requiredPlan = [
  'Включила компьютер: изучила релизы, обновления и передала важную информацию команде в чат',
  'Зашла в почту: прочитала письма от РГ и смежных подразделений, ответила, проанализировала и зафиксировала вопросы',
  'Открыла УК ЕСЗК: сверилась с расписанием, планом по часам, ACSAT критической зоны, CSAT и показателями проектов',
  'Утреннее целеполагание: вспомнила договорённости с РГ, выбрала зону роста и поставила цель в штуках и процентах',
  'Пятиминутки с РГ в 12:00, 15:00 и 18:00: подготовила сводку план/факт, статистику, штуки в час, согласия и действия',
  'В конце смены: отправила РГ рефлексию с цифрами, результатами, зоной роста и корректировками на следующую смену',
];

const makeId = () => crypto.randomUUID();
const today = () => new Date().toISOString().slice(0, 10);
const initialState: AppState = {
  started: false, startedAt: null,
  products: productNames.map((name, index) => ({ id: `product-${index}`, name, calls: 0, consents: 0, sales: 0, crossSales: 0, hours: 0, consentTarget: 10, ppsTarget: 5, salesHourTarget: 1, crossTarget: 1 })),
  tasks: requiredPlan.map((title, index) => ({ id: `required-${index}`, title, required: true, priority: (index < 2 ? 'Высокий' : 'Средний') as Task['priority'], due: '', done: false })),
  quality: { csat: { value: 0, target: 80, direction: 'min', snapshots: [] }, critical: { value: 0, target: 80, direction: 'min', snapshots: [] }, green: { value: 0, target: 80, direction: 'min', snapshots: [] } },
  logs: [], victories: [], diary: [], history: [], breaks: ['12:00', '15:00', '18:00'], profile: { name: 'Сотрудник', team: 'Исходящий телемаркетинг' }, lastSaved: null
};

function normalizeState(data: Partial<AppState>): AppState {
  const savedTasks = Array.isArray(data.tasks) ? data.tasks : [];
  const personalTasks = savedTasks.filter(task => !task.required);
  const savedRequired = new Map(savedTasks.filter(task => task.required).map(task => [task.id, task]));
  return { ...initialState, ...data, tasks: requiredPlan.map((title, index) => ({ id: `required-${index}`, title, required: true, priority: (index < 2 ? 'Высокий' : 'Средний') as Task['priority'], due: '', done: Boolean(savedRequired.get(`required-${index}`)?.done) })).concat(personalTasks) };
}

function loadLocal(): AppState {
  try { const raw = localStorage.getItem('shift-planner-state'); return raw ? normalizeState(JSON.parse(raw) as Partial<AppState>) : initialState; } catch { return initialState; }
}

function pct(value: number, total: number) { return total ? Math.round((value / total) * 100) : 0; }
function parseNum(str: string): number { const cleaned = str.replace(',', '.').replace(/[^\d.]/g, ''); return cleaned === '' || cleaned === '.' ? 0 : Number(cleaned) || 0; }
function NumInput({ value, onCommit, placeholder }: { value: number; onCommit: (v: number) => void; placeholder?: string }) { const [text, setText] = useState(String(value)); useEffect(() => setText(String(value)), [value]); return <input type="text" inputMode="decimal" value={text} onChange={e => setText(e.target.value)} onBlur={() => onCommit(parseNum(text))} onFocus={e => { if (text === '0') e.currentTarget.select(); }} placeholder={placeholder} />; }
function formatDate(value: string) { return new Date(`${value}T12:00:00`).toLocaleDateString('ru-RU', { day: 'numeric', month: 'long' }); }
function recommendation(product: Product) {
  if (!product.calls) return 'Добавь первый снимок показателей — тогда появится точная рекомендация.';
  const consent = pct(product.consents, product.calls); const pps = pct(product.sales, product.calls);
  if (consent < product.consentTarget) return `Согласия ниже цели на ${product.consentTarget - consent} п.п. Проверь, насколько ясно ты объясняешь выгоду продукта.`;
  if (pps < product.ppsTarget) return 'Согласия растут, но PPS пока отстаёт. Посмотри, на каком этапе клиент отказывается от оформления.';
  if (product.sales / Math.max(product.hours, 1) < product.salesHourTarget) return 'Продажи в час ниже цели. Выбери один фокус на ближайшие звонки и не торопи клиента.';
  return 'Показатели держатся в цели. Сохрани спокойный темп и зафиксируй, что сегодня сработало.';
}

function App() {
  const [state, setState] = useState<AppState>(loadLocal);
  const [page, setPage] = useState<Page>('home');
  const [loading, setLoading] = useState(true);
  const [notice, setNotice] = useState('');
  const [showQuick, setShowQuick] = useState(false);
  const [showPause, setShowPause] = useState(false);
  const [showSummary, setShowSummary] = useState(false);
  const [showVictory, setShowVictory] = useState(false);
  const [showDiary, setShowDiary] = useState(false);
  const [showEmail, setShowEmail] = useState(false);
  const [showMobileMenu, setShowMobileMenu] = useState(false);
  const [selectedTip, setSelectedTip] = useState<string | null>(null);
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [timer, setTimer] = useState(300);
  const [timerRunning, setTimerRunning] = useState(false);

  useEffect(() => {
    let active = true;
    async function fetchState() {
      if (!supabase) { setLoading(false); return; }
      const { data } = await supabase.from('shift_planner_state').select('data').eq('id', 'default').maybeSingle();
      if (active && data?.data) setState(normalizeState(data.data as Partial<AppState>));
      if (active) setLoading(false);
    }
    void fetchState();
    return () => { active = false; };
  }, []);

  useEffect(() => {
    if (loading) return;
    localStorage.setItem('shift-planner-state', JSON.stringify(state));
    const save = async () => {
      const saved = { ...state, lastSaved: new Date().toISOString() };
      localStorage.setItem('shift-planner-state', JSON.stringify(saved));
      setState(current => current.lastSaved ? current : saved);
      if (supabase) await supabase.from('shift_planner_state').upsert({ id: 'default', data: saved, updated_at: new Date().toISOString() });
    };
    const handle = window.setTimeout(() => void save(), 500);
    return () => window.clearTimeout(handle);
  }, [state, loading]);

  useEffect(() => { if (!timerRunning) return; const handle = window.setInterval(() => setTimer(value => value > 0 ? value - 1 : 0), 1000); return () => window.clearInterval(handle); }, [timerRunning]);
  useEffect(() => { if (timer === 0) setTimerRunning(false); }, [timer]);
  useEffect(() => { window.scrollTo({ top: 0, behavior: 'smooth' }); }, [page]);

  const totals = useMemo(() => state.products.reduce((acc, product) => ({ calls: acc.calls + product.calls, consents: acc.consents + product.consents, sales: acc.sales + product.sales, cross: acc.cross + product.crossSales }), { calls: 0, consents: 0, sales: 0, cross: 0 }), [state.products]);
  const doneTasks = state.tasks.filter(task => task.done).length;
  const nextBreak = state.breaks.find(item => item > new Date().toTimeString().slice(0, 5)) ?? state.breaks[0];

  function updateState(updater: (current: AppState) => AppState) { setState(current => updater(current)); setNotice('Сохранено'); window.setTimeout(() => setNotice(''), 1800); }
  function startShift() { updateState(current => ({ ...current, started: true, startedAt: new Date().toISOString() })); }
  function finishShift() {
    const entry: ShiftHistory = { id: makeId(), date: today(), tasksDone: doneTasks, tasksTotal: state.tasks.length, products: state.products, quality: { csat: state.quality.csat.value, critical: state.quality.critical.value, green: state.quality.green.value }, victories: state.victories.filter(item => item.date === today()), diary: state.diary.find(item => item.date === today()) };
    updateState(current => ({ ...current, started: false, history: [entry, ...current.history] }));
    setPage('history');
  }
  function updateProduct(id: string, patch: Partial<Product>) { updateState(current => ({ ...current, products: current.products.map(product => product.id === id ? { ...product, ...patch } : product) })); }
  function addSnapshot(id: string, calls: number, consents: number, sales: number, crossSales: number, hours: number) {
    updateState(current => ({ ...current, products: current.products.map(product => product.id === id ? { ...product, calls, consents, sales, crossSales, hours } : product) }));
  }
  function updateQuality(key: 'csat' | 'critical' | 'green', value: number, target?: number) { updateState(current => { const metric = current.quality[key]; return { ...current, quality: { ...current.quality, [key]: { ...metric, value, target: target ?? metric.target, snapshots: [...metric.snapshots, { value, at: new Date().toISOString() }] } } }; }); }
  function addTask(title: string, priority: Task['priority'], due: string) { updateState(current => ({ ...current, tasks: [...current.tasks, { id: makeId(), title, required: false, priority, due, done: false }] })); }
  function copyText(text: string) { void navigator.clipboard?.writeText(text); setNotice('Скопировано'); window.setTimeout(() => setNotice(''), 1800); }
  function exportData() { const blob = new Blob([JSON.stringify(state, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `мой-план-${today()}.json`; link.click(); URL.revokeObjectURL(url); }
  function importData(file: File) { const reader = new FileReader(); reader.onload = () => { try { setState({ ...initialState, ...JSON.parse(String(reader.result)) }); setNotice('Резервная копия восстановлена'); } catch { setNotice('Не удалось прочитать файл'); } }; reader.readAsText(file); }
  const summary = `Мой план на смену — ${formatDate(today())}\n\nЗвонки: ${totals.calls}\nСогласия: ${totals.consents} (${pct(totals.consents, totals.calls)}%)\nПродажи: ${totals.sales} (${pct(totals.sales, totals.calls)}%)\nКросс-продажи: ${totals.cross}\n\nCSAT: ${state.quality.csat.value}% | ACSAT критическая: ${state.quality.critical.value}% | ACSAT зелёная: ${state.quality.green.value}%\n\nФокус: ${recommendation(state.products.find(product => product.calls) ?? state.products[0])}`;
  const morningEmail = `Доброе утро!\n\nМои цели на смену:\n${state.products.map(product => `— ${product.name}: согласия ${product.consentTarget}%, PPS ${product.ppsTarget}%, продаж/час ${product.salesHourTarget}`).join('\n')}\n— CSAT: ${state.quality.csat.target}%\n— ACSAT критическая зона: ${state.quality.critical.target}%\n— ACSAT зелёная зона: ${state.quality.green.target}%\n\nСегодня держу фокус на ясной презентации и спокойном завершении разговора.`;
  const eveningEmail = `Добрый вечер!\n\nРефлексия по итогам смены — ${formatDate(today())}\n\nЗвонки: ${totals.calls}\nСогласия: ${totals.consents} (${pct(totals.consents, totals.calls)}%)\nПродажи: ${totals.sales} (${pct(totals.sales, totals.calls)}%)\nКросс-продажи: ${totals.cross}\n\nCSAT: ${state.quality.csat.value}% | ACSAT критическая: ${state.quality.critical.value}% | ACSAT зелёная: ${state.quality.green.value}%\n\nЧто получилось:\n— \n\nЧто не получилось:\n— \n\nЧто нужно улучшить:\n— \n\nКорректировки на следующую смену и что это даст:\n— `;

  if (loading) return <div className="loading-screen"><Sparkles size={28} /><span>Собираю твой рабочий стол…</span></div>;

  return <div className="app-shell">
    {showMobileMenu && <button className="mobile-menu-backdrop" aria-label="Закрыть меню" onClick={() => setShowMobileMenu(false)} />}
    <aside className={showMobileMenu ? 'sidebar mobile-open' : 'sidebar'}>
      <div className="brand"><span className="brand-mark">✦</span><div>мой план<br /><b>на смену</b></div><button className="mobile-menu-close" aria-label="Закрыть меню" onClick={() => setShowMobileMenu(false)}><X size={18} /></button></div>
      <nav>{([['home', LayoutDashboard, 'Мой день'], ['tasks', ClipboardList, 'План'], ['targets', Target, 'Цели и показатели'], ['journal', Archive, 'Журнал продаж'], ['history', History, 'История смен'], ['library', BookOpen, 'Памятки'], ['settings', Settings, 'Профиль'] ] as const).map(([id, Icon, label]) => <button key={id} className={page === id ? 'nav-item active' : 'nav-item'} onClick={() => { setPage(id); setShowMobileMenu(false); }}><Icon size={18} /><span>{label}</span></button>)}</nav>
      <div className="sidebar-bottom"><div className="cat-small">◡ᴥ◡</div><span>офисный выживальщик</span></div>
    </aside>
    <main className="main-content">
      <header className="topbar"><button className="mobile-menu" aria-label="Открыть меню" onClick={() => setShowMobileMenu(value => !value)}><Menu size={20} /></button><div className="breadcrumbs">{page === 'home' ? 'Мой день' : page === 'targets' ? 'Цели и показатели' : page === 'journal' ? 'Журнал продаж' : page === 'library' ? 'Памятки' : page === 'history' ? 'История смен' : page === 'tasks' ? 'План на смену' : 'Профиль и настройки'}</div><div className="top-actions"><span className="saved-indicator"><span className="save-dot" /> {state.lastSaved ? 'сохранено' : 'локально'}</span><button className="icon-button" aria-label="Уведомления" onClick={() => { setNotice('Новых уведомлений нет'); window.setTimeout(() => setNotice(''), 1800); }}><Bell size={18} /></button><button className="profile-chip" aria-label="Открыть профиль" onClick={() => setPage('settings')}><span>{state.profile.name.slice(0, 1)}</span><small>{state.profile.name}</small></button></div></header>
      {page === 'home' && <Home state={state} totals={totals} doneTasks={doneTasks} nextBreak={nextBreak} startShift={startShift} finishShift={finishShift} setShowQuick={setShowQuick} setShowSummary={setShowSummary} setShowVictory={setShowVictory} setShowDiary={setShowDiary} setShowPause={setShowPause} setShowEmail={setShowEmail} setPage={setPage} />}
      {page === 'tasks' && <Tasks state={state} doneTasks={doneTasks} updateState={updateState} editingTask={editingTask} setEditingTask={setEditingTask} addTask={addTask} />}
      {page === 'targets' && <Targets state={state} updateProduct={updateProduct} addSnapshot={addSnapshot} updateQuality={updateQuality} />}
      {page === 'journal' && <Journal state={state} updateState={updateState} />}
      {page === 'history' && <HistoryPage state={state} updateState={updateState} />}
      {page === 'library' && <Library onOpen={setSelectedTip} />}
      {page === 'settings' && <SettingsPage state={state} updateState={updateState} exportData={exportData} importData={importData} />}
    </main>
    {notice && <div className="toast"><Check size={15} />{notice}</div>}
    {showQuick && <QuickEntry state={state} setShowQuick={setShowQuick} addSnapshot={addSnapshot} updateQuality={updateQuality} />}
    {showSummary && <Modal title="Сводка перед пятиминуткой" onClose={() => setShowSummary(false)}><pre className="summary-text">{summary}</pre><button className="primary-button wide" onClick={() => copyText(summary)}><Copy size={16} />Копировать сводку</button></Modal>}
    {showEmail && <EmailModal morning={morningEmail} evening={eveningEmail} onClose={() => setShowEmail(false)} onCopy={copyText} />}
    {showVictory && <Modal title="Маленькая победа" onClose={() => setShowVictory(false)}><VictoryForm updateState={updateState} onDone={() => setShowVictory(false)} /></Modal>}
    {showDiary && <Modal title="Дневник зоны роста" onClose={() => setShowDiary(false)}><DiaryForm updateState={updateState} existing={state.diary.find(item => item.date === today())} onDone={() => setShowDiary(false)} /></Modal>}
    {selectedTip && <TipDetails title={selectedTip} onClose={() => setSelectedTip(null)} />}
    {showPause && <Modal title="Минутка отдыха" onClose={() => { setShowPause(false); setTimerRunning(false); }}><div className="pause-view"><div className="breath-orb"><Heart size={30} /></div><strong>{String(Math.floor(timer / 60)).padStart(2, '0')}:{String(timer % 60).padStart(2, '0')}</strong><p>Вдох на четыре счёта. Выдох на шесть.<br />Котик официально разрешает не быть машиной.</p><div className="modal-actions"><button className="ghost-button" onClick={() => { setTimer(300); setTimerRunning(false); }}>Сбросить</button><button className="primary-button" onClick={() => setTimerRunning(value => !value)}>{timerRunning ? <Pause size={16} /> : <Play size={16} />}{timerRunning ? 'Пауза' : 'Начать'}</button></div></div></Modal>}
  </div>;
}

function Home({ state, totals, doneTasks, nextBreak, startShift, finishShift, setShowQuick, setShowSummary, setShowVictory, setShowDiary, setShowPause, setShowEmail, setPage }: { state: AppState; totals: { calls: number; consents: number; sales: number; cross: number }; doneTasks: number; nextBreak: string; startShift: () => void; finishShift: () => void; setShowQuick: (value: boolean) => void; setShowSummary: (value: boolean) => void; setShowVictory: (value: boolean) => void; setShowDiary: (value: boolean) => void; setShowPause: (value: boolean) => void; setShowEmail: (value: boolean) => void; setPage: (value: Page) => void }) {
  const progress = pct(doneTasks, state.tasks.length); const focus = state.products.find(product => product.calls) ?? state.products[0];
  return <div className="page home-page"><section className="hero"><div><div className="eyebrow"><span className="live-dot" />{state.started ? 'смена идёт' : 'смена ещё не началась'} · {formatDate(today())}</div><h1>Твоя смена.<br /><em>Твой темп.</em></h1><p>Планируй по-своему. Замечай прогресс.<br />Не забывай выдыхать.</p><div className="hero-actions">{state.started ? <button className="primary-button" onClick={finishShift}>Завершить смену <CheckCircle2 size={17} /></button> : <button className="primary-button" onClick={startShift}>Начать смену <ArrowRight size={17} /></button>}<button className="soft-button" onClick={() => setShowQuick(true)}><CirclePlus size={17} /> Внести результат</button></div></div><div className="hero-art"><div className="bubble bubble-a" /><div className="bubble bubble-b" /><div className="glass-cat"><svg viewBox="0 0 200 240" className="cat-svg" fill="none" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="glassBody" x1="0" y1="0" x2="1" y2="1"><stop offset="0%" stopColor="rgba(255,255,255,.85)" /><stop offset="40%" stopColor="rgba(230,210,218,.45)" /><stop offset="100%" stopColor="rgba(170,170,140,.4)" /></linearGradient><linearGradient id="glassShine" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="rgba(255,255,255,.95)" /><stop offset="100%" stopColor="rgba(255,255,255,0)" /></linearGradient><radialGradient id="cheekG" cx=".5" cy=".5"><stop offset="0%" stopColor="rgba(210,140,158,.5)" /><stop offset="100%" stopColor="rgba(210,140,158,0)" /></radialGradient></defs><ellipse cx="100" cy="225" rx="55" ry="6" fill="rgba(108,91,89,.12)" /><path d="M60 35 L72 18 L85 45 Z" fill="url(#glassBody)" stroke="rgba(255,255,255,.9)" strokeWidth="1" /><path d="M140 35 L128 18 L115 45 Z" fill="url(#glassBody)" stroke="rgba(255,255,255,.9)" strokeWidth="1" /><path d="M62 38 L71 25 L80 42 Z" fill="rgba(190,150,165,.3)" /><path d="M138 38 L129 25 L120 42 Z" fill="rgba(190,150,165,.3)" /><ellipse cx="100" cy="120" rx="62" ry="88" fill="url(#glassBody)" stroke="rgba(255,255,255,.9)" strokeWidth="1.5" /><path d="M55 75 Q70 55 78 150 Q65 180 50 160 Q42 120 55 75 Z" fill="url(#glassShine)" opacity=".75" /><ellipse cx="75" cy="100" rx="20" ry="12" fill="rgba(255,255,255,.6)" transform="rotate(-25 75 100)" /><path d="M100 62 Q92 58 85 66 Q92 70 100 66 Q108 70 115 66 Q108 58 100 62 Z" fill="rgba(160,130,142,.35)" stroke="rgba(255,255,255,.5)" strokeWidth=".8" /><ellipse cx="82" cy="108" rx="7" ry="12" fill="rgba(80,75,70,.7)" /><ellipse cx="118" cy="108" rx="7" ry="12" fill="rgba(80,75,70,.7)" /><ellipse cx="84" cy="104" rx="2.5" ry="5" fill="rgba(255,255,255,.85)" /><ellipse cx="120" cy="104" rx="2.5" ry="5" fill="rgba(255,255,255,.85)" /><ellipse cx="68" cy="128" rx="12" ry="7" fill="url(#cheekG)" /><ellipse cx="132" cy="128" rx="12" ry="7" fill="url(#cheekG)" /><path d="M94 128 L100 134 L106 128 L100 132 Z" fill="rgba(180,150,160,.5)" stroke="rgba(255,255,255,.4)" strokeWidth=".5" /><path d="M100 134 Q96 142 90 140 M100 134 Q104 142 110 140" stroke="rgba(120,100,110,.5)" strokeWidth="1.2" strokeLinecap="round" fill="none" /><line x1="55" y1="126" x2="78" y2="122" stroke="rgba(120,100,110,.35)" strokeWidth=".7" /><line x1="55" y1="134" x2="78" y2="132" stroke="rgba(120,100,110,.35)" strokeWidth=".7" /><line x1="145" y1="126" x2="122" y2="122" stroke="rgba(120,100,110,.35)" strokeWidth=".7" /><line x1="145" y1="134" x2="122" y2="132" stroke="rgba(120,100,110,.35)" strokeWidth=".7" /><rect x="75" y="152" width="50" height="6" rx="3" fill="#c78d9e" opacity=".8" /><circle cx="100" cy="155" r="3" fill="rgba(255,255,255,.6)" /><path d="M42 200 Q38 210 48 215" stroke="rgba(200,170,180,.4)" strokeWidth="2" fill="none" strokeLinecap="round" /><path d="M158 200 Q162 210 152 215" stroke="rgba(200,170,180,.4)" strokeWidth="2" fill="none" strokeLinecap="round" /></svg><small>office<br />survivor</small></div><div className="scribble">ты<br />можешь<br />больше ♡</div></div></section>
    <div className="quick-strip"><span><Clock3 size={16} />Следующая пятиминутка <b>{nextBreak}</b></span><span className="strip-divider" /><span>до встречи спокойно успеваешь разобрать фокус</span><button onClick={() => setShowSummary(true)}>Открыть сводку <ArrowRight size={15} /></button></div>
    <section className="dashboard-grid"><div className="card plan-card"><CardHeading icon={<Target size={18} />} title="План на смену" action={`${doneTasks}/${state.tasks.length}`} onClick={() => setPage('tasks')} /><div className="progress-line"><span style={{ width: `${progress}%` }} /></div><div className="progress-caption"><b>{progress}%</b><span>обязательные пункты</span></div><div className="task-preview">{state.tasks.slice(0, 4).map(task => <div key={task.id} className={task.done ? 'task-row done' : 'task-row'}><span className="check-circle">{task.done && <Check size={12} />}</span><span>{task.title}</span></div>)}</div><button className="text-link" onClick={() => setPage('tasks')}>Открыть весь план <ArrowRight size={15} /></button></div><div className="card focus-card"><CardHeading icon={<Sparkles size={18} />} title="Сегодня в фокусе" /><div className="focus-list"><div><b>01</b><span>Больше уверенности<br />в разговоре</span></div><div><b>02</b><span>Проверять согласие<br />и предлагать кросс</span></div><div><b>03</b><span>Сохранять спокойствие<br />и хорошее настроение</span></div></div><div className="hand-note">small steps ♡</div></div><div className="card metrics-card"><CardHeading icon={<BarChart3 size={18} />} title="Мой прогресс" action="сегодня" onClick={() => setPage('targets')} /><div className="donut-wrap"><div className="donut"><strong>{pct(totals.sales, Math.max(totals.calls, 1))}%</strong><span>продажи</span></div><div className="metric-list"><div><i className="pink-dot" />Согласия <b>{pct(totals.consents, totals.calls)}%</b></div><div><i className="olive-dot" />Продажи <b>{pct(totals.sales, totals.calls)}%</b></div><div><i className="rose-dot" />CSAT <b>{state.quality.csat.value || '—'}%</b></div><div><i className="lilac-dot" />ACSAT <b>{state.quality.green.value || '—'}%</b></div></div></div><button className="text-link" onClick={() => setPage('targets')}>Подробнее о целях <ArrowRight size={15} /></button></div></section>
    <section className="insight-banner"><div className="banner-cat">◡ᴥ◡</div><div><strong>{totals.calls ? 'Ты уже в ритме.' : 'Смена начинается с одного звонка.'}</strong><p>{totals.calls ? `Главная зона внимания: ${focus.name}. ${recommendation(focus)}` : 'Внеси первый снимок показателей, чтобы увидеть персональные подсказки.'}</p></div><button className="round-arrow" onClick={() => setShowQuick(true)}><ArrowRight size={18} /></button></section>
    <section className="lower-grid"><div className="card day-card"><CardHeading icon={<Activity size={18} />} title="Твой день" action={formatDate(today())} /><div className="day-stats"><Stat label="Звонки" value={totals.calls} icon={<PhoneCall size={17} />} /><Stat label="Согласия" value={totals.consents} icon={<BadgeCheck size={17} />} /><Stat label="Продажи" value={totals.sales} icon={<ShoppingBag size={17} />} /><Stat label="Кросс-продажи" value={totals.cross} icon={<Sparkles size={17} />} /></div><div className="day-actions"><button className="soft-button" onClick={() => setShowVictory(true)}><Trophy size={15} /> Добавить победу</button><button className="ghost-button" onClick={() => setShowDiary(true)}><Pencil size={15} /> Зона роста</button></div></div><div className="card attention-card"><CardHeading icon={<TrendingDown size={18} />} title="На что обратить внимание" /><div className="recommendation"><span className="rec-icon">!</span><div><b>{focus.name}</b><p>{recommendation(focus)}</p></div></div><div className="attention-actions"><button className="ghost-button" onClick={() => setShowPause(true)}><Heart size={15} /> Мне нужна пауза</button><button className="ghost-button" onClick={() => setShowEmail(true)}><FileText size={15} /> Письмо РГ</button></div></div></section>
    <section className="library-preview"><div className="section-title"><div><span className="eyebrow">полезные материалы</span><h2>Подсказки, которые работают</h2></div><button className="text-link" onClick={() => setPage('library')}>Вся библиотека <ArrowRight size={15} /></button></div><div className="tip-grid">{tipItems.map(([tag, title, desc], index) => <button className={`tip-card tip-${index}`} key={tag} onClick={() => setPage('library')}><span>{tag}</span><div className="tip-shape">{index === 0 ? '♡' : index === 1 ? '◌' : index === 2 ? '✧' : '∞'}</div><strong>{title}</strong><small>{desc}</small></button>)}</div></section>
  </div>;
}

function CardHeading({ icon, title, action, onClick }: { icon: React.ReactNode; title: string; action?: string; onClick?: () => void }) { return <div className="card-heading"><div><span className="heading-icon">{icon}</span><h3>{title}</h3></div>{action && <button className="card-action" onClick={onClick}>{action}{onClick && <ChevronRight size={13} />}</button>}</div>; }
function Stat({ label, value, icon }: { label: string; value: number | string; icon: React.ReactNode }) { return <div className="stat"><span>{icon}</span><small>{label}</small><strong>{value}</strong></div>; }

function Tasks({ state, doneTasks, updateState, editingTask, setEditingTask, addTask }: { state: AppState; doneTasks: number; updateState: (updater: (current: AppState) => AppState) => void; editingTask: Task | null; setEditingTask: (task: Task | null) => void; addTask: (title: string, priority: Task['priority'], due: string) => void }) {
  const [title, setTitle] = useState(''); const [priority, setPriority] = useState<Task['priority']>('Средний'); const [due, setDue] = useState('');
  return <div className="page"><PageIntro eyebrow="план на смену" title="Что сегодня важно" subtitle={`${doneTasks} из ${state.tasks.length} пунктов уже отмечены. Обязательные задачи и личные фокусы живут рядом, но не смешиваются.`} /><div className="task-layout"><section className="card task-panel"><CardHeading icon={<Flag size={18} />} title="Обязательные пункты" action={`${state.tasks.filter(item => item.required && item.done).length}/${state.tasks.filter(item => item.required).length}`} />{state.tasks.filter(item => item.required).map(task => <TaskItem task={task} key={task.id} onToggle={() => updateState(current => ({ ...current, tasks: current.tasks.map(item => item.id === task.id ? { ...item, done: !item.done } : item) }))} onEdit={() => setEditingTask(task)} onDelete={() => updateState(current => ({ ...current, tasks: current.tasks.filter(item => item.id !== task.id) }))} />)}</section><section className="card task-panel"><CardHeading icon={<Sparkles size={18} />} title="Мои задачи" action={`${state.tasks.filter(item => !item.required && item.done).length}/${state.tasks.filter(item => !item.required).length}`} />{state.tasks.filter(item => !item.required).length === 0 && <EmptyState text="Добавь личный фокус на сегодня" />}{state.tasks.filter(item => !item.required).map(task => <TaskItem task={task} key={task.id} onToggle={() => updateState(current => ({ ...current, tasks: current.tasks.map(item => item.id === task.id ? { ...item, done: !item.done } : item) }))} onEdit={() => setEditingTask(task)} onDelete={() => updateState(current => ({ ...current, tasks: current.tasks.filter(item => item.id !== task.id) }))} />)}<div className="add-task-form"><input value={title} onChange={event => setTitle(event.target.value)} placeholder="Например, разобрать сложный кейс" /><div className="form-row"><select value={priority} onChange={event => setPriority(event.target.value as Task['priority'])}><option>Высокий</option><option>Средний</option><option>Низкий</option></select><input value={due} onChange={event => setDue(event.target.value)} placeholder="Срок, например 15:00" /><button className="primary-button" onClick={() => { if (title.trim()) { addTask(title.trim(), priority, due); setTitle(''); setDue(''); } }}><Plus size={16} />Добавить</button></div></div></section></div>{editingTask && <Modal title="Изменить задачу" onClose={() => setEditingTask(null)}><EditTask task={editingTask} updateState={updateState} onDone={() => setEditingTask(null)} /></Modal>}</div>;
}
function TaskItem({ task, onToggle, onEdit, onDelete }: { task: Task; onToggle: () => void; onEdit: () => void; onDelete: () => void }) { return <div className={task.done ? 'task-item done' : 'task-item'}><button className="task-check" onClick={onToggle}>{task.done && <Check size={14} />}</button><div><strong>{task.title}</strong><small>{task.priority}{task.due && ` · до ${task.due}`}</small></div><div className="task-actions"><button onClick={onEdit}><Edit3 size={15} /></button><button onClick={onDelete}><Trash2 size={15} /></button></div></div>; }
function EditTask({ task, updateState, onDone }: { task: Task; updateState: (updater: (current: AppState) => AppState) => void; onDone: () => void }) { const [title, setTitle] = useState(task.title); const [priority, setPriority] = useState(task.priority); const [due, setDue] = useState(task.due); return <div className="form-stack"><label>Название<input value={title} onChange={event => setTitle(event.target.value)} /></label><label>Приоритет<select value={priority} onChange={event => setPriority(event.target.value as Task['priority'])}><option>Высокий</option><option>Средний</option><option>Низкий</option></select></label><label>Срок<input value={due} onChange={event => setDue(event.target.value)} placeholder="необязательно" /></label><button className="primary-button" onClick={() => { updateState(current => ({ ...current, tasks: current.tasks.map(item => item.id === task.id ? { ...item, title, priority, due } : item) })); onDone(); }}>Сохранить</button></div>; }

function Targets({ state, updateProduct, addSnapshot, updateQuality }: { state: AppState; updateProduct: (id: string, patch: Partial<Product>) => void; addSnapshot: (id: string, calls: number, consents: number, sales: number, crossSales: number, hours: number) => void; updateQuality: (key: 'csat' | 'critical' | 'green', value: number, target?: number) => void }) { const [selected, setSelected] = useState(state.products[0].id); const product = state.products.find(item => item.id === selected) ?? state.products[0]; const [draft, setDraft] = useState({ calls: product.calls, consents: product.consents, sales: product.sales, crossSales: product.crossSales, hours: product.hours }); useEffect(() => setDraft({ calls: product.calls, consents: product.consents, sales: product.sales, crossSales: product.crossSales, hours: product.hours }), [selected, product.calls, product.consents, product.sales, product.crossSales, product.hours]); return <div className="page"><PageIntro eyebrow="цели и показатели" title="Твои цифры, без магии" subtitle="Каждый замер — это общий накопленный итог. Новый снимок заменяет текущий, но не стирает историю изменений." /><div className="product-tabs">{state.products.map(item => <button className={item.id === selected ? 'selected' : ''} key={item.id} onClick={() => setSelected(item.id)}>{item.name}</button>)}</div><div className="target-layout"><section className="card entry-card"><CardHeading icon={<RefreshCw size={18} />} title="Новый снимок показателей" action="общий итог" /><p className="muted">Введи то, что сейчас видишь в рабочей системе. Предыдущие значения не прибавляются.</p><div className="number-grid">{(['calls', 'consents', 'sales', 'crossSales', 'hours'] as const).map(key => <label key={key}>{key === 'calls' ? 'Звонки' : key === 'consents' ? 'Согласия' : key === 'sales' ? 'Продажи' : key === 'crossSales' ? 'Кросс-продажи' : 'Часов по продукту'}<NumInput value={draft[key]} onCommit={v => setDraft(current => ({ ...current, [key]: v }))} /></label>)}</div><button className="primary-button" onClick={() => addSnapshot(product.id, draft.calls, draft.consents, draft.sales, draft.crossSales, draft.hours)}>Сохранить общий итог <Check size={16} /></button></section><section className="card product-card"><CardHeading icon={<BarChart3 size={18} />} title={product.name} action={product.calls ? 'есть данные' : 'данных пока нет'} /><div className="big-metrics"><div><small>Согласия</small><strong>{pct(product.consents, product.calls)}%</strong><span>цель {product.consentTarget}%</span></div><div><small>PPS</small><strong>{pct(product.sales, product.calls)}%</strong><span>цель {product.ppsTarget}%</span></div><div><small>Продаж/час</small><strong>{(product.sales / Math.max(product.hours, 1)).toFixed(1)}</strong><span>цель {product.salesHourTarget}</span></div><div><small>Кросс-продажи</small><strong>{product.crossSales}</strong><span>цель {product.crossTarget}</span></div></div><div className="recommendation compact"><span className="rec-icon">✦</span><p>{recommendation(product)}</p></div><div className="target-edit"><TargetInput label="Цель согласий, %" value={product.consentTarget} onChange={value => updateProduct(product.id, { consentTarget: value })} /><TargetInput label="Цель PPS, %" value={product.ppsTarget} onChange={value => updateProduct(product.id, { ppsTarget: value })} /><TargetInput label="Продаж в час" value={product.salesHourTarget} onChange={value => updateProduct(product.id, { salesHourTarget: value })} /><TargetInput label="Цель кросс-продаж" value={product.crossTarget} onChange={value => updateProduct(product.id, { crossTarget: value })} /></div></section></div><section className="quality-section"><div className="section-title"><div><span className="eyebrow">качество разговора</span><h2>CSAT и ACSAT</h2></div><span className="muted">Цели задаёшь ты — приложение не придумывает нормативы.</span></div><div className="quality-grid">{([['critical', 'ACSAT — критическая зона'], ['green', 'ACSAT — зелёная зона'], ['csat', 'CSAT']] as const).map(([key, label]) => <QualityCard key={key} label={label} metric={state.quality[key]} onSave={(value, target) => updateQuality(key, value, target)} />)}</div></section></div>; }
function TargetInput({ label, value, onChange }: { label: string; value: number; onChange: (value: number) => void }) { return <label>{label}<NumInput value={value} onCommit={onChange} /></label>; }
function QualityCard({ label, metric, onSave }: { label: string; metric: QualityMetric; onSave: (value: number, target: number) => void }) { const [value, setValue] = useState(metric.value); const [target, setTarget] = useState(metric.target); const delta = value - target; return <div className="card quality-card"><div className="quality-icon"><Activity size={18} /></div><h3>{label}</h3><div className="quality-values"><div><small>сейчас</small><strong>{value}%</strong></div><div><small>цель</small><strong>{target}%</strong></div><div><small>разница</small><strong className={delta >= 0 ? 'good' : 'bad'}>{delta > 0 ? '+' : ''}{delta} п.п.</strong></div></div><div className="quality-inputs"><NumInput value={value} onCommit={setValue} placeholder="Текущий %" /><NumInput value={target} onCommit={setTarget} placeholder="Цель %" /><button className="primary-button" onClick={() => onSave(value, target)}>Обновить</button></div><p>{value >= target ? 'Цель достигнута. Продолжай держать спокойный темп.' : `До цели осталось ${target - value} процентных пунктов. Обрати внимание на точность формулировок и завершение разговора.`}</p></div>; }

function QuickEntry({ state, setShowQuick, addSnapshot, updateQuality }: { state: AppState; setShowQuick: (value: boolean) => void; addSnapshot: (id: string, calls: number, consents: number, sales: number, crossSales: number, hours: number) => void; updateQuality: (key: 'csat' | 'critical' | 'green', value: number) => void }) { const [productId, setProductId] = useState(state.products[0].id); const product = state.products.find(item => item.id === productId) ?? state.products[0]; const [values, setValues] = useState({ calls: product.calls, consents: product.consents, sales: product.sales, crossSales: product.crossSales, hours: product.hours }); useEffect(() => setValues({ calls: product.calls, consents: product.consents, sales: product.sales, crossSales: product.crossSales, hours: product.hours }), [productId, product.calls, product.consents, product.sales, product.crossSales, product.hours]); return <Modal title="Внести результаты" onClose={() => setShowQuick(false)}><div className="form-stack"><label>Продукт<select value={productId} onChange={event => setProductId(event.target.value)}>{state.products.map(item => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><div className="number-grid">{(['calls', 'consents', 'sales', 'crossSales', 'hours'] as const).map(key => <label key={key}>{key === 'calls' ? 'Звонки' : key === 'consents' ? 'Согласия' : key === 'sales' ? 'Продажи' : key === 'crossSales' ? 'Кросс-продажи' : 'Часов'}<NumInput value={values[key]} onCommit={v => setValues(current => ({ ...current, [key]: v }))} /></label>)}</div><div className="quality-mini"><label>CSAT<NumInput value={state.quality.csat.value} onCommit={v => updateQuality('csat', v)} /></label><label>ACSAT крит.<NumInput value={state.quality.critical.value} onCommit={v => updateQuality('critical', v)} /></label><label>ACSAT зел.<NumInput value={state.quality.green.value} onCommit={v => updateQuality('green', v)} /></label></div><button className="primary-button wide" onClick={() => { addSnapshot(product.id, values.calls, values.consents, values.sales, values.crossSales, values.hours); setShowQuick(false); }}>Сохранить снимок <Check size={16} /></button></div></Modal>; }

function Journal({ state, updateState }: { state: AppState; updateState: (updater: (current: AppState) => AppState) => void }) { const [tab, setTab] = useState<'sale' | 'cross'>('sale'); const [product, setProduct] = useState(state.products[0].name); const [comment, setComment] = useState(''); const filtered = state.logs.filter(item => item.type === tab); return <div className="page"><PageIntro eyebrow="журнал продаж" title="Фиксируй важные моменты" subtitle="Продажи и кросс-продажи видны отдельно, чтобы статистика оставалась честной." /><div className="journal-layout"><section className="card log-form"><div className="segmented"><button className={tab === 'sale' ? 'selected' : ''} onClick={() => setTab('sale')}>Продажи</button><button className={tab === 'cross' ? 'selected' : ''} onClick={() => setTab('cross')}>Кросс-продажи</button></div><label>Продукт<select value={product} onChange={event => setProduct(event.target.value)}>{state.products.map(item => <option key={item.id}>{item.name}</option>)}</select></label><label>Комментарий<textarea value={comment} onChange={event => setComment(event.target.value)} placeholder="Что помогло клиенту принять решение?" /></label><button className="primary-button" onClick={() => { if (!comment.trim()) return; updateState(current => ({ ...current, logs: [{ id: makeId(), type: tab, product, at: new Date().toISOString(), comment }, ...current.logs] })); setComment(''); }}>Добавить запись <Plus size={16} /></button></section><section className="card log-list"><CardHeading icon={<Archive size={18} />} title={tab === 'sale' ? 'Продажи' : 'Кросс-продажи'} action={`${filtered.length} записей`} />{filtered.length === 0 && <EmptyState text="Записей пока нет" />}{filtered.map(item => <div className="log-item" key={item.id}><div className="log-time">{new Date(item.at).toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' })}</div><div><strong>{item.product}</strong><p>{item.comment}</p></div><button onClick={() => updateState(current => ({ ...current, logs: current.logs.filter(log => log.id !== item.id) }))}><Trash2 size={15} /></button></div>)}</section></div></div>; }

function HistoryPage({ state, updateState }: { state: AppState; updateState: (updater: (current: AppState) => AppState) => void }) { return <div className="page"><PageIntro eyebrow="история смен" title="Ты уже многое сделала" subtitle="Завершённые смены сохраняются отдельно и не меняются, когда ты редактируешь цели." /><div className="history-list">{state.history.length === 0 && <div className="card empty-large"><History size={30} /><h3>Первая смена ещё впереди</h3><p>Заверши текущую смену, и она появится здесь отдельной карточкой.</p></div>}{state.history.map(item => <div className="card history-card" key={item.id}><div className="history-date"><span>{formatDate(item.date)}</span><div className="history-meta"><b>{item.tasksDone}/{item.tasksTotal} задач</b><button className="history-delete" aria-label="Удалить смену" onClick={() => updateState(current => ({ ...current, history: current.history.filter(entry => entry.id !== item.id) }))}><Trash2 size={15} /></button></div></div><div className="history-product-grid">{item.products.filter(product => product.calls || product.sales).slice(0, 4).map(product => <div key={product.id}><small>{product.name}</small><strong>{product.sales} продаж</strong><span>{product.calls} звонков · {pct(product.sales, product.calls)}% PPS</span></div>)}</div><div className="history-quality"><span>CSAT <b>{item.quality.csat}%</b></span><span>ACSAT крит. <b>{item.quality.critical}%</b></span><span>ACSAT зел. <b>{item.quality.green}%</b></span><span><Trophy size={14} /> {item.victories.length} побед</span></div></div>)}</div></div>; }

function Library({ onOpen }: { onOpen: (title: string) => void }) { const [search, setSearch] = useState(''); const [favorites, setFavorites] = useState<string[]>([]); const [onlyFavorites, setOnlyFavorites] = useState(false); const items = [...tipItems, ['Начало разговора', 'Первые секунды задают тон', 'Представься, обозначь цель и оставь клиенту пространство.'], ['Эмпатия', 'Сначала услышать', 'Назови эмоцию клиента, не споря с ней.'], ['Интонация', 'Спокойствие слышно', 'Чуть медленнее — и важное звучит увереннее.'], ['Презентация продукта', 'Выгода вместо каталога', 'Свяжи предложение с тем, что уже рассказал клиент.'], ['Вопросы клиента', 'Вопрос — это интерес', 'Ответь коротко и верни разговор к ценности.'], ['Завершение разговора', 'Оставь хорошее послевкусие', 'Повтори договорённость и поблагодари за время.']].filter(item => item.join(' ').toLowerCase().includes(search.toLowerCase()) && (!onlyFavorites || favorites.includes(item[1]))); return <div className="page"><PageIntro eyebrow="библиотека памяток" title="Нужная фраза — под рукой" subtitle="Коммерческий разговор, в котором забота и результат не спорят друг с другом." /><div className="library-toolbar"><div className="search-box"><Search size={17} /><input value={search} onChange={event => setSearch(event.target.value)} placeholder="Найти памятку" /></div><button className={onlyFavorites ? 'soft-button selected-filter' : 'soft-button'} onClick={() => setOnlyFavorites(value => !value)}><Heart size={15} /> {onlyFavorites ? 'Все памятки' : 'Избранное'}</button></div><div className="library-grid">{items.map(([tag, title, desc], index) => <article className={`library-card library-${index % 4}`} key={title} onClick={() => onOpen(title)}><div className="library-card-top"><span>{tag}</span><button aria-label="Добавить в избранное" onClick={event => { event.stopPropagation(); setFavorites(current => current.includes(title) ? current.filter(item => item !== title) : [...current, title]); }}><Heart size={16} fill={favorites.includes(title) ? 'currentColor' : 'none'} /></button></div><div className="tip-shape">{index % 4 === 0 ? '♡' : index % 4 === 1 ? '◌' : index % 4 === 2 ? '✧' : '∞'}</div><h3>{title}</h3><p>{desc}</p><button className="text-link" onClick={() => onOpen(title)}>Открыть памятку <ArrowRight size={15} /></button></article>)}</div>{items.length === 0 && <div className="card empty-large"><Search size={28} /><h3>Ничего не нашлось</h3><p>Попробуй другое слово или открой все памятки.</p></div>}</div>; }

function TipDetails({ title, onClose }: { title: string; onClose: () => void }) { const item = [...tipItems, ['Начало разговора', 'Первые секунды задают тон', 'Представься, обозначь цель и оставь клиенту пространство.'], ['Эмпатия', 'Сначала услышать', 'Назови эмоцию клиента, не споря с ней.'], ['Интонация', 'Спокойствие слышно', 'Чуть медленнее — и важное звучит увереннее.'], ['Презентация продукта', 'Выгода вместо каталога', 'Свяжи предложение с тем, что уже рассказал клиент.'], ['Вопросы клиента', 'Вопрос — это интерес', 'Ответь коротко и верни разговор к ценности.'], ['Завершение разговора', 'Оставь хорошее послевкусие', 'Повтори договорённость и поблагодари за время.']].find(entry => entry[1] === title); return <Modal title={item?.[0] ?? 'Памятка'} onClose={onClose}><div className="tip-detail"><div className="tip-detail-shape">✦</div><h3>{item?.[1] ?? title}</h3><p>{item?.[2] ?? 'Открой эту памятку перед звонком и выбери одну фразу для ближайшего разговора.'}</p><div className="detail-block"><b>Попробуй сегодня</b><p>Сначала коротко презентуй предложение, затем задай уточняющий вопрос и оставь клиенту место для ответа.</p></div><div className="detail-block"><b>Важно</b><p>Не обещай результат и не дави. Твоя задача — говорить ясно, спокойно и по делу.</p></div></div></Modal>; }

function SettingsPage({ state, updateState, exportData, importData }: { state: AppState; updateState: (updater: (current: AppState) => AppState) => void; exportData: () => void; importData: (file: File) => void }) { const [name, setName] = useState(state.profile.name); const [team, setTeam] = useState(state.profile.team); return <div className="page"><PageIntro eyebrow="профиль и настройки" title="Настрой пространство под себя" subtitle="Данные сохраняются автоматически после каждого изменения. Резервная копия всегда остаётся в твоих руках." /><div className="settings-grid"><section className="card settings-card"><CardHeading icon={<UserRound size={18} />} title="Профиль" /><label>Имя<input value={name} onChange={event => setName(event.target.value)} onBlur={() => updateState(current => ({ ...current, profile: { ...current.profile, name } }))} /></label><label>Команда<input value={team} onChange={event => setTeam(event.target.value)} onBlur={() => updateState(current => ({ ...current, profile: { ...current.profile, team } }))} /></label><button className="primary-button" onClick={() => updateState(current => ({ ...current, profile: { name, team } }))}>Сохранить профиль</button></section><section className="card settings-card"><CardHeading icon={<Clock3 size={18} />} title="Пятиминутки" /><p className="muted">Расписание относится к рабочему дню и не влияет на месячные цели.</p>{state.breaks.map((time, index) => <div className="break-row" key={`${time}-${index}`}><input type="time" value={time} onChange={event => updateState(current => ({ ...current, breaks: current.breaks.map((item, i) => i === index ? event.target.value : item) }))} /><button onClick={() => updateState(current => ({ ...current, breaks: current.breaks.filter((_, i) => i !== index) }))}><Trash2 size={15} /></button></div>)}<button className="soft-button" onClick={() => updateState(current => ({ ...current, breaks: [...current.breaks, '19:00'] }))}><Plus size={15} /> Добавить время</button></section><section className="card settings-card"><CardHeading icon={<Download size={18} />} title="Данные и резервная копия" /><p className="muted">Экспортируй данные перед сменой устройства или восстанови ранее сохранённый файл.</p><div className="settings-actions"><button className="primary-button" onClick={exportData}><Download size={16} /> Экспортировать</button><label className="ghost-button file-button"><UploadIcon /> Импортировать<input type="file" accept="application/json" onChange={event => { const file = event.target.files?.[0]; if (file) importData(file); }} /></label></div></section></div></div>; }
function UploadIcon() { return <Archive size={16} />; }

function PageIntro({ eyebrow, title, subtitle }: { eyebrow: string; title: string; subtitle: string }) { return <div className="page-intro"><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{subtitle}</p></div>; }
function EmptyState({ text }: { text: string }) { return <div className="empty-state"><Sparkles size={18} /><span>{text}</span></div>; }
function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) { return <div className="modal-backdrop" onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}><div className="modal"><div className="modal-header"><h2>{title}</h2><button onClick={onClose}><X size={18} /></button></div>{children}</div></div>; }
function EmailModal({ morning, evening, onClose, onCopy }: { morning: string; evening: string; onClose: () => void; onCopy: (text: string) => void }) { const [tab, setTab] = useState<'morning' | 'evening'>('morning'); const text = tab === 'morning' ? morning : evening; return <Modal title="Письмо руководителю" onClose={onClose}><div className="email-tabs"><button className={tab === 'morning' ? 'selected' : ''} onClick={() => setTab('morning')}>Утреннее целеполагание</button><button className={tab === 'evening' ? 'selected' : ''} onClick={() => setTab('evening')}>Вечерняя рефлексия</button></div><textarea className="large-textarea" defaultValue={text} key={tab} /><div className="modal-actions"><button className="ghost-button" onClick={() => onCopy(text)}><Copy size={16} />Копировать</button><button className="primary-button" onClick={onClose}>Готово</button></div></Modal>; }
function VictoryForm({ updateState, onDone }: { updateState: (updater: (current: AppState) => AppState) => void; onDone: () => void }) { const [text, setText] = useState(''); const choices = ['Сохранила спокойствие в сложном разговоре', 'Поймала хороший темп', 'Сделала понятную презентацию']; return <div className="form-stack"><div className="choice-list">{choices.map(choice => <button key={choice} onClick={() => setText(choice)}>{choice}<ChevronRight size={15} /></button>)}</div><label>Или напиши свою<input value={text} onChange={event => setText(event.target.value)} placeholder="Моя маленькая победа…" /></label><button className="primary-button" onClick={() => { if (text.trim()) updateState(current => ({ ...current, victories: [...current.victories, { id: makeId(), text: text.trim(), date: today() }] })); onDone(); }}>Сохранить победу <Trophy size={16} /></button></div>; }
function DiaryForm({ updateState, existing, onDone }: { updateState: (updater: (current: AppState) => AppState) => void; existing?: Diary; onDone: () => void }) { const [form, setForm] = useState({ worked: existing?.worked ?? '', changed: existing?.changed ?? '', result: existing?.result ?? '', next: existing?.next ?? '' }); const field = (key: keyof typeof form, label: string, placeholder: string) => <label>{label}<textarea value={form[key]} onChange={event => setForm(current => ({ ...current, [key]: event.target.value }))} placeholder={placeholder} /></label>; return <div className="form-stack">{field('worked', 'Над чем работала', 'Например, над ясностью презентации')}{field('changed', 'Что попробовала изменить', 'Один небольшой эксперимент')}{field('result', 'Какой результат получила', 'Что заметила в разговоре')}{field('next', 'Что попробовать в следующую смену', 'Без давления, просто следующий шаг')}<button className="primary-button" onClick={() => { updateState(current => ({ ...current, diary: [...current.diary.filter(item => item.date !== today()), { id: existing?.id ?? makeId(), date: today(), ...form }] })); onDone(); }}>Сохранить запись <Check size={16} /></button></div>; }

export default App;
